// Package references renders every generated output (CONTRIBUTING.md, "Generated files").
package references

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/pyahu/initializer/internal/guidedata"
)

// Header starts every generated Markdown file.
const Header = "<!-- Generated by guidekit generate. Do not edit. -->"

// AreaOrder is the page order of reference areas.
var AreaOrder = []string{"java", "jeps", "spring-boot", "spring-framework", "spring-data", "spring-security",
	"spring-modulith", "architecture", "database", "testing", "observability", "build", "kubernetes", "api",
	"identity", "ci", "supply-chain", "dependencies", "static-analysis", "messaging", "cache"}

// AreaTitle names each area on the page.
var AreaTitle = map[string]string{
	"java": "Java and the JDK", "jeps": "JEPs", "spring-boot": "Spring Boot", "spring-framework": "Spring Framework",
	"spring-data": "Spring Data", "spring-security": "Spring Security", "spring-modulith": "Spring Modulith",
	"architecture": "jMolecules and ArchUnit", "database": "Liquibase, PostgreSQL, pgJDBC", "testing": "Testcontainers",
	"observability": "OpenTelemetry and Micrometer", "build": "Gradle", "kubernetes": "Kubernetes and Kustomize",
	"api": "OpenAPI and its generator", "identity": "OIDC and OAuth 2.0", "ci": "GitHub Actions",
	"supply-chain": "Supply chain", "dependencies": "Renovate", "static-analysis": "NullAway, JSpecify, Error Prone",
	"messaging": "Messaging", "cache": "Cache",
}

// Outputs maps repository-relative paths to generated content.
type Outputs map[string][]byte

// Generate renders every output.
func Generate(r *guidedata.Repo) (Outputs, error) {
	out := Outputs{}
	page, err := ReferencePage(r)
	if err != nil {
		return nil, err
	}
	out["guides/src/content/docs/reference/docs.md"] = page
	gj, err := GuidesJSON(r)
	if err != nil {
		return nil, err
	}
	out["guides/src/generated/guides.json"] = gj
	ff, err := FixtureFiles(r)
	if err != nil {
		return nil, err
	}
	out["guides/src/generated/fixture-files.json"] = ff
	for _, fx := range r.Fixtures {
		b, err := FixtureReferences(r, fx)
		if err != nil {
			return nil, err
		}
		out[r.Rel(filepath.Join(fx.Dir, "docs", "references.md"))] = b
	}
	return out, nil
}

// Write writes the outputs; Check reports the ones that differ from disk.
func (o Outputs) Write(root string) error {
	for p, b := range o {
		full := filepath.Join(root, p)
		if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(full, b, 0o644); err != nil {
			return err
		}
	}
	return nil
}

// Check lists generated files that are missing or stale.
func (o Outputs) Check(root string) []string {
	var stale []string
	for p, b := range o {
		cur, err := os.ReadFile(filepath.Join(root, p))
		if err != nil || !bytes.Equal(cur, b) {
			stale = append(stale, p)
		}
	}
	sort.Strings(stale)
	return stale
}

func entriesFor(r *guidedata.Repo, baseline string, options map[string]any) []guidedata.ReferenceEntry {
	var es []guidedata.ReferenceEntry
	for _, e := range r.References.Entries {
		if !contains(e.Baselines, baseline) {
			continue
		}
		if options != nil && !guidedata.Matches(e.AppliesWhen, options) {
			continue
		}
		es = append(es, e)
	}
	return es
}

func cell(s string) string { return strings.ReplaceAll(strings.ReplaceAll(s, "|", "\\|"), "\n", " ") }

func versionOf(r *guidedata.Repo, baseline string, e guidedata.ReferenceEntry) string {
	if e.Component != nil {
		if rev := r.Versions.Revision(baseline); rev != nil {
			if c, ok := rev.Components[*e.Component]; ok {
				if e.DocVersion != c.Version && e.Match != "exact" {
					return fmt.Sprintf("%s (docs %s)", c.Version, e.DocVersion)
				}
				return c.Version
			}
		}
	}
	return e.DocVersion
}

func renderEntries(b *strings.Builder, r *guidedata.Repo, baseline string, es []guidedata.ReferenceEntry, level string) {
	byArea := map[string][]guidedata.ReferenceEntry{}
	for _, e := range es {
		byArea[e.Area] = append(byArea[e.Area], e)
	}
	for _, area := range AreaOrder {
		list := byArea[area]
		if len(list) == 0 {
			continue
		}
		fmt.Fprintf(b, "%s %s\n\n", level, AreaTitle[area])
		if area == "jeps" {
			b.WriteString("| JEP | Title | Status | Release | Read it for |\n| --- | ----- | ------ | ------- | ----------- |\n")
			sort.SliceStable(list, func(i, j int) bool { return list[i].JEP.Number < list[j].JEP.Number })
			for _, e := range list {
				fmt.Fprintf(b, "| [%d](%s) | %s | %s | JDK %s | %s |\n", e.JEP.Number, e.URL, cell(e.JEP.Title), cell(e.JEP.Status), cell(e.JEP.Release), cell(e.Purpose))
			}
			b.WriteString("\n")
			continue
		}
		b.WriteString("| Document | Version | Pinned | Read it for |\n| -------- | ------- | ------ | ----------- |\n")
		for _, e := range list {
			pinned := "pinned"
			if !e.Pinned {
				pinned = "not version-pinned"
			}
			fmt.Fprintf(b, "| [%s](%s) | %s | %s | %s |\n", cell(e.Title), e.URL, cell(versionOf(r, baseline, e)), pinned, cell(e.Purpose))
		}
		b.WriteString("\n")
	}
}

// ReferencePage renders guides/src/content/docs/reference/docs.md for the active baseline.
func ReferencePage(r *guidedata.Repo) ([]byte, error) {
	active := r.Versions.Active
	idx := r.Versions.RevisionIndex(active)
	if idx < 0 {
		return nil, fmt.Errorf("active baseline %s not found", active)
	}
	es := entriesFor(r, active, nil)
	var b strings.Builder
	b.WriteString("---\ntitle: Reference docs\ndescription: Official documentation for the exact versions the guides and the generator use.\ntableOfContents: { maxHeadingLevel: 2 }\n---\n\n")
	b.WriteString(Header + "\n\n")
	fmt.Fprintf(&b, "Baseline **%s**. Every link points to the documentation for the version in that baseline; links that cannot be pinned say \"not version-pinned\".\n\n", active)
	if gaps := ReferenceGaps(r); len(gaps) > 0 {
		fmt.Fprintf(&b, ":::caution[Re-verify]\nThese components had entries in the previous baseline and have none in %s: %s.\n:::\n\n", active, strings.Join(gaps, ", "))
	}
	renderEntries(&b, r, active, es, "##")
	b.WriteString("## By guide\n\n")
	for _, g := range r.Guides {
		fmt.Fprintf(&b, "### [%s](/guides/%s/)\n\n", g.Title, g.Meta.ID)
		n := 0
		for _, e := range es {
			if contains(e.Guides, g.Meta.ID) {
				fmt.Fprintf(&b, "- [%s](%s)\n", e.Title, e.URL)
				n++
			}
		}
		if n == 0 {
			b.WriteString("- None yet.\n")
		}
		b.WriteString("\n")
	}
	b.WriteString("## Upstream llms.txt\n\n")
	seen := map[string]bool{}
	for _, e := range es {
		if e.LLMs != nil && !seen[e.LLMs.Txt] {
			seen[e.LLMs.Txt] = true
			line := fmt.Sprintf("- %s", e.LLMs.Txt)
			if e.LLMs.Full != "" {
				line += fmt.Sprintf(" (full: %s)", e.LLMs.Full)
			}
			b.WriteString(line + "\n")
		}
	}
	return []byte(b.String()), nil
}

// ReferenceGaps lists components of the active revision that had entries in the previous
// revision and have none in the active one.
func ReferenceGaps(r *guidedata.Repo) []string {
	idx := r.Versions.RevisionIndex(r.Versions.Active)
	if idx <= 0 {
		return nil
	}
	prev := r.Versions.Revisions[idx-1].ID
	had, has := map[string]bool{}, map[string]bool{}
	for _, e := range r.References.Entries {
		if e.Component == nil {
			continue
		}
		if contains(e.Baselines, prev) {
			had[*e.Component] = true
		}
		if contains(e.Baselines, r.Versions.Active) {
			has[*e.Component] = true
		}
	}
	var gaps []string
	for c := range had {
		if !has[c] {
			gaps = append(gaps, c)
		}
	}
	sort.Strings(gaps)
	return gaps
}

// FixtureReferences renders fixtures/<name>/docs/references.md.
func FixtureReferences(r *guidedata.Repo, fx guidedata.Fixture) ([]byte, error) {
	es := entriesFor(r, fx.Baseline, fx.Options)
	var b strings.Builder
	b.WriteString(Header + "\n\n# References\n\n")
	fmt.Fprintf(&b, "Official documentation for this project's versions (baseline %s), filtered to its options. Start here when you need the source for a decision.\n\n", fx.Baseline)
	renderEntries(&b, r, fx.Baseline, es, "##")
	return []byte(b.String()), nil
}

// FixtureFiles renders guides/src/generated/fixture-files.json .
func FixtureFiles(r *guidedata.Repo) ([]byte, error) {
	type file struct {
		Path     string `json:"path"`
		Fixture  string `json:"fixture"`
		Baseline string `json:"baseline"`
		Lang     string `json:"lang"`
		Sha256   string `json:"sha256"`
	}
	byPath := map[string]file{}
	for _, g := range r.Guides {
		for _, rc := range g.Recipes {
			if _, ok := byPath[rc.Path]; ok {
				continue
			}
			parts := strings.SplitN(rc.Path, "/", 3)
			if len(parts) < 3 {
				return nil, fmt.Errorf("recipe %s: bad path %s", rc.ID, rc.Path)
			}
			fx := r.Fixture(parts[1])
			if fx == nil {
				return nil, fmt.Errorf("recipe %s: no fixture %s", rc.ID, parts[1])
			}
			b, err := os.ReadFile(filepath.Join(r.Root, rc.Path))
			if err != nil {
				return nil, err
			}
			sum := sha256.Sum256(b)
			byPath[rc.Path] = file{Path: rc.Path, Fixture: fx.Name, Baseline: fx.Baseline, Lang: rc.Lang, Sha256: hex.EncodeToString(sum[:])}
		}
	}
	paths := make([]string, 0, len(byPath))
	for p := range byPath {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	files := make([]file, 0, len(paths))
	for _, p := range paths {
		files = append(files, byPath[p])
	}
	return marshal(map[string]any{"generatedBy": "guidekit generate", "files": files})
}

func marshal(v any) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(v); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func contains(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}
